const CAPABILITIES = [
  {
    icon: AgencyClientApprovalIcon,
    title: "Agency-to-Client Approval Workflows",
    desc: "Route work from agency creators through internal review to client reviewers and approvers — with evidence records created at every hand-off.",
  },
  {
    icon: MultiBrandWorkspaceIcon,
    title: "Multi-Brand Workspace Separation",
    desc: "Isolate each client brand in its own workspace with independent brand standards, approval rules, role permissions, and audit records.",
  },
  {
    icon: AIGovernanceClientIcon,
    title: "AI Governance for Client Work",
    desc: "Apply agency review and mandatory client sign-off to all AI-assisted content — with records showing client authorization, not just agency approval.",
  },
  {
    icon: ClientEvidenceRecordsIcon,
    title: "Client Evidence Records",
    desc: "Preserve a complete, exportable record of every client approval, change, policy trigger, and publication event — for every client account.",
  },
  {
    icon: ExternalCollaboratorIcon,
    title: "External Collaborator Controls",
    desc: "Manage freelancer, contractor, and partner access with defined workspace boundaries and permission levels — without cross-client data risk.",
  },
  {
    icon: ExecutiveVisibilityIcon,
    title: "Executive Visibility Across Accounts",
    desc: "Give agency leaders visibility into workflow status, approval bottlenecks, and governance health across all client accounts from a single view.",
  },
];

export default function AgenciesCapabilities() {
  return (
    <section className="bg-[#080d1a] py-24">
      <div className="max-w-7xl mx-auto px-6 lg:px-12">
        <div className="text-center mb-14">
          <div className="inline-flex items-center gap-2 mb-4">
            <span className="w-4 h-px bg-[#20E7F2]" />
            <span className="text-[10px] font-bold uppercase tracking-[0.2em] text-[#20E7F2]">Platform Capabilities</span>
          </div>
          <h2 className="text-[clamp(1.8rem,3.5vw,2.6rem)] font-black leading-tight text-white max-w-2xl mx-auto">
            Governance capabilities for agencies and multi-brand teams.
          </h2>
        </div>

        <div className="grid sm:grid-cols-2 lg:grid-cols-3 gap-6">
          {CAPABILITIES.map((c) => (
            <div key={c.title} className="rounded-2xl border border-white/[0.08] bg-[#101D2F] p-7">
              <div
                className="flex items-center justify-center mb-5"
                style={{
                  width: 44,
                  height: 44,
                  borderRadius: 11,
                  border: "1px solid rgba(201, 168, 76, 0.25)",
                  background: "rgba(201, 168, 76, 0.12)",
                }}
              >
                <c.icon className="w-[19px] h-[19px]" />
              </div>
              <h3 className="text-white font-bold text-[15px] mb-2 leading-snug">{c.title}</h3>
              <p className="text-white/50 text-[13.5px] leading-relaxed">{c.desc}</p>
            </div>
          ))}
        </div>
      </div>
    </section>
  );
}
